"use strict";(self.webpackChunksketch_blog=self.webpackChunksketch_blog||[]).push([[2877],{1776(a,p,e){e.r(p),e.d(p,{_pageData:()=>h,default:()=>t});var s=e(641);const h=JSON.parse('{"path":"/notes/%E4%B9%A6%E5%BD%B1%E9%9F%B3%E6%B8%B8/%E8%A7%86%E9%A2%91/%E6%B5%81%E6%B5%AA%E5%9C%B0%E7%90%832.html","title":"流浪地球2","lang":"zh-CN","frontmatter":{"title":"流浪地球2","date":"2023-04-23T00:00:00.000Z","tags":["影视"]},"git":{},"filePathRelative":"notes/书影音游/视频/流浪地球2.md"}'),n={name:"流浪地球2.md"},t=(0,e(6262).A)(n,[["render",function(a,p,e,h,n,t){return(0,s.uX)(),(0,s.CE)("div",null,[...p[0]||(p[0]=[(0,s.Fv)('<h1 id="流浪地球2" tabindex="-1"><a class="header-anchor" href="#流浪地球2"><span>流浪地球2</span></a></h1><p>历经太空电梯事件、移山计划受阻事件、月球危机事件后，地球成功开启流浪之旅的故事。</p><h2 id="三条线" tabindex="-1"><a class="header-anchor" href="#三条线"><span>三条线</span></a></h2><p>整个故事有三条线，刘培强线、图恒宇线、联合国线</p><p>刘培强线主要在说移山计划</p><p>图恒宇线主要围绕数字生命</p><p>联合国线。。宣扬流浪地球中的思想主旋律。周似乎是发现了moss有自主意识的</p><h2 id="数字生命" tabindex="-1"><a class="header-anchor" href="#数字生命"><span>数字生命</span></a></h2><p>电影是以moss视角叙述的，因为每个事件发生前都有明确的计时。</p><p>moss的自主意识如何形成以及如何操纵这些事件发生的有大佬分析，在此不提。</p><p>说一说数字生命。</p><p>数字生命是把记忆copy成数据的一种技术。</p><h3 id="数字生命-永生" tabindex="-1"><a class="header-anchor" href="#数字生命-永生"><span>数字生命===永生？</span></a></h3><p><s>如果人没有灵魂，数字生命可以当做假的永生。</s></p><p><s>如果人有灵魂，数字生命就是电子宠物。</s></p><p>数字生命不管怎么说都是由算力根据存储的记忆去计算你每一步的行动的，那么数字生命是不是并没有真正的活着</p><p>你活着也可以将你存储的每个阶段的记忆变为数字生命。那么是不是可以说：数字生命除了有你的记忆外，和“你”再没有任何关系。</p><p>还有我觉得人是有灵魂的，我相信死后还会有轮回（没有论证，纯粹因为我不想人死如灯灭..）</p><p>所以我觉得数字生命就是个骗人的把戏，图恒宇将他女儿的数字生命拉长只是无用的执念..用来消除他自身对女儿的愧疚感。</p>',19)])])}]])}}]);